using System.Globalization;
using System.Resources;
using EncDotNet.S100.Collections.Library;

namespace EncDotNet.S100.Viewer.Resources;

/// <summary>
/// Strongly-typed accessor for the viewer's UI strings (see Strings.resx).
/// Every user-visible string in the viewer is exposed here so the UI can be
/// localized by adding satellite resources without touching XAML or code.
/// </summary>
/// <remarks>
/// Hand-written rather than generated by ResXFileCodeGenerator so that
/// <c>dotnet build</c> alone (no Visual Studio designer) keeps the file in
/// sync. When adding a new key:
/// <list type="number">
///   <item>Add the <c>&lt;data&gt;</c> entry to <c>Strings.resx</c>.</item>
///   <item>Add a matching property below.</item>
/// </list>
/// </remarks>
internal static class Strings
{
    private static readonly ResourceManager ResourceManager =
        new("EncDotNet.S100.Viewer.Resources.Strings", typeof(Strings).Assembly);

    /// <summary>The current UI culture used to look up strings.</summary>
    public static CultureInfo Culture { get; set; } = CultureInfo.CurrentUICulture;

    // The Library's shared text (item tags and details, status lines) lives in
    // EncDotNet.S100.Collections (#792); keys not found here are looked up there.
    private static string Get(string name) =>
        ResourceManager.GetString(name, Culture) ?? LibraryText.Find(name, Culture) ?? name;

    /// <summary>
    /// Returns the curated human-readable product title for a spec code
    /// (e.g. <c>"S-101"</c> → "Electronic Navigational Chart"), or
    /// <c>null</c> when the spec is not in the curated map. Lookup keys drop
    /// the hyphen from the spec code (<c>"S-101"</c> → <c>SpecName_S101</c>).
    /// </summary>
    public static string? SpecDisplayName(string spec) =>
        string.IsNullOrEmpty(spec)
            ? null
            : LibraryText.Find("SpecName_" + spec.Replace("-", string.Empty), Culture);

    /// <summary>
    /// Returns a readable label for a library item property key (e.g.
    /// <c>riverMiles</c> → "River miles"), or <c>null</c> when the key has no
    /// curated label. Lookup keys are <c>Library_Property_&lt;key&gt;</c>.
    /// </summary>
    public static string? LibraryPropertyLabel(string key) =>
        string.IsNullOrEmpty(key) ? null : LibraryText.Find("Library_Property_" + key, Culture);

